INSERT INTO `ai_alert_explain` VALUES (1,3689,20005,1004,201,1,5,'RED','ABSENCE','你所在的大学计算机基础（一）01班触发红灯预警，触发规则为 A_HARD_LINE，触发类型是缺勤超限。系统记录显示，你缺课 6 次，已超过允许上限 4 次。该课程规则明确，缺课超过三分之一会直接影响课程通过，因此系统按红灯预警处理。这一预警只说明考勤维度已触及硬性界限，不代表对你学习能力的判定。','{\"late\": 0, \"leave\": 0, \"absent\": 6, \"termId\": 5, \"alertId\": 3689, \"classAvg\": 78.058889, \"courseId\": 1, \"hardFail\": true, \"nearFail\": true, \"className\": \"大学计算机基础（一） 01班\", \"classRank\": 37, \"classSize\": 45, \"studentId\": 1004, \"studentNo\": \"20250005\", \"alertLevel\": \"RED\", \"confidence\": 1.0, \"courseName\": \"大学计算机基础（一）\", \"failReason\": \"HARD_LINE\", \"outputMode\": \"FULL_SCORE\", \"totalScore\": 68.35, \"weakGroups\": [{\"name\": \"简答题\", \"rate\": 0.822727}], \"alertReason\": \"缺课 6 次，已超过允许上限 4 次（缺课超 1/3 直接挂科）\", \"projectDone\": 0, \"studentName\": \"周敏\", \"triggerRule\": \"A_HARD_LINE\", \"triggerType\": \"ABSENCE\", \"classAvgText\": \"78.1\", \"enrollmentId\": 20005, \"allowedAbsent\": 4, \"finalNeedText\": \"67.9\", \"weightedScore\": 80.4, \"projectMissing\": 0, \"totalScoreText\": \"68.4\", \"triggerChannel\": \"A\", \"confidenceLevel\": \"HIGH\", \"deductionPoints\": 12.0, \"finalExamNeeded\": 67.9, \"homeworkMissing\": 0, \"projectExpected\": 0, \"remainingAbsent\": -2, \"riskCourseCount\": 1, \"teachingClassId\": 201, \"triggerTypeText\": \"缺勤超限\", \"homeworkExpected\": 2, \"homeworkSubmitted\": 11}','{\"actions\": [{\"type\": \"ABSENCE_TALK\", \"label\": \"找任课老师说明缺勤原因\", \"payload\": {\"enrollmentId\": 20005, \"teachingClassId\": 201}}, {\"type\": \"ABSENCE_RECORD\", \"label\": \"核对考勤记录（缺勤 6 次 / 允许 4 次）\", \"payload\": {\"enrollmentId\": 20005}}, {\"type\": \"ABSENCE_FULL\", \"label\": \"剩余课时全勤，把缺勤控制在当前次数\", \"payload\": {\"enrollmentId\": 20005}}], \"summary\": \"你所在的大学计算机基础（一）01班触发红灯预警，触发规则为 A_HARD_LINE，触发类型是缺勤超限。系统记录显示，你缺课 6 次，已超过允许上限 4 次。该课程规则明确，缺课超过三分之一会直接影响课程通过，因此系统按红灯预警处理。这一预警只说明考勤维度已触及硬性界限，不代表对你学习能力的判定。\", \"sections\": [{\"text\": \"你所在的大学计算机基础（一）01班触发红灯预警，触发规则为 A_HARD_LINE，触