--
-- Table structure for table `ai_grading_suggest`
--

DROP TABLE IF EXISTS `ai_grading_suggest`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_grading_suggest` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `submission_id` bigint NOT NULL COMMENT '提交记录ID',
  `answer_id` bigint NOT NULL COMMENT 'submission_answer.id（一条答案一条建议）',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `teaching_class_id` bigint NOT NULL,
  `q_type` varchar(20) NOT NULL COMMENT 'SHORT / BLANK',
  `full_score` decimal(6,2) NOT NULL COMMENT '本题满分',
  `student_answer` text COMMENT '学生作答（快照，便于事后复盘）',
  `ref_answer` text COMMENT '参考要点快照',
  `suggested_score` decimal(6,2) NOT NULL COMMENT 'AI 建议分',
  `comment` varchar(500) DEFAULT NULL COMMENT 'AI 评语',
  `rubric_json` json DEFAULT NULL COMMENT '模型给的评分要点（可展示给教师）',
  `checks_json` json DEFAULT NULL COMMENT '三道校验结果：scoreRange / commentDigits / refExists',
  `source` varchar(20) NOT NULL DEFAULT 'LLM' COMMENT 'LLM / TEMPLATE',
  `model` varchar(50) DEFAULT NULL,
  `prompt_version` varchar(20) DEFAULT NULL,
  `run_id` bigint DEFAULT NULL,
  `tokens` int DEFAULT NULL,
  `cost` decimal(10,6) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'SUGGESTED' COMMENT 'SUGGESTED / APPLIED / IGNORED',
  `final_score` decimal(6,2) DEFAULT NULL COMMENT '教师最终采纳/修改后的分数',
  `final_comment` varchar(500) DEFAULT NULL COMMENT '教师最终评语',
  `reviewer_id` bigint DEFAULT NULL,
  `review_time` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_answer` (`answer_id`),
  KEY `idx_submission` (`submission_id`),
  KEY `idx_tc_status` (`teaching_class_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 批改建议（不改分数，仅建议）';
/*!40101 SET character_set_client = @saved_cs_client */;

