--
-- Table structure for table `ai_group_report`
--

DROP TABLE IF EXISTS `ai_group_report`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_group_report` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scope` varchar(20) NOT NULL COMMENT 'CLASS=教学班报告 / ADMIN_CLASS=行政班报告',
  `target_id` bigint NOT NULL COMMENT '教学班ID 或 行政班ID',
  `teaching_class_id` bigint DEFAULT NULL,
  `admin_class_id` bigint DEFAULT NULL,
  `offering_id` bigint DEFAULT NULL,
  `course_id` bigint DEFAULT NULL,
  `term_id` bigint DEFAULT NULL,
  `title` varchar(120) NOT NULL COMMENT '如「计基01班 · 班级学情报告」',
  `fact_json` json DEFAULT NULL COMMENT '生成所用事实（可复算）',
  `content_json` json DEFAULT NULL COMMENT '段落与动作',
  `summary` varchar(300) DEFAULT NULL COMMENT '一句话结论',
  `status` varchar(20) NOT NULL DEFAULT 'PUBLISHED',
  `source` varchar(20) NOT NULL DEFAULT 'TEMPLATE' COMMENT 'DIFY / LLM / TEMPLATE',
  `model` varchar(50) DEFAULT NULL,
  `app_id` varchar(64) DEFAULT NULL,
  `prompt_version` varchar(20) DEFAULT NULL,
  `run_id` bigint DEFAULT NULL,
  `tokens` int DEFAULT NULL,
  `cost` decimal(10,6) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL COMMENT '教师/辅导员ID',
  `publish_time` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_scope_target` (`scope`,`target_id`,`create_time`),
  KEY `idx_class` (`teaching_class_id`,`create_time`),
  KEY `idx_admin_class` (`admin_class_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 群体学情报告';
/*!40101 SET character_set_client = @saved_cs_client */;

