--
-- Table structure for table `ai_qa_log`
--

DROP TABLE IF EXISTS `ai_qa_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_qa_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` bigint NOT NULL,
  `course_id` bigint NOT NULL,
  `teaching_class_id` bigint DEFAULT NULL,
  `question` varchar(500) NOT NULL,
  `answer` text,
  `citations_json` json DEFAULT NULL COMMENT '引用：[{docName,sectionNo}]',
  `hit_count` int NOT NULL DEFAULT '0',
  `top_score` decimal(8,4) DEFAULT NULL COMMENT '最高相关度',
  `refused` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=无依据拒答',
  `retrieval_mode` varchar(16) DEFAULT NULL COMMENT '检索模式：FULLTEXT/VECTOR/HYBRID',
  `retrieval_json` json DEFAULT NULL COMMENT '检索诊断：各路命中/名次/融合分/耗时',
  `status` varchar(20) NOT NULL DEFAULT 'OK' COMMENT 'OK / REFUSAL / FALLBACK',
  `source` varchar(20) DEFAULT NULL COMMENT 'LLM / TEMPLATE',
  `tokens` int DEFAULT NULL,
  `cost` decimal(10,6) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_student` (`student_id`,`create_time`),
  KEY `idx_course` (`course_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 课程答疑记录';
/*!40101 SET character_set_client = @saved_cs_client */;

