DROP TABLE IF EXISTS `ai_rag_eval_case`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_rag_eval_case` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `course_id` bigint NOT NULL,
  `question` varchar(500) NOT NULL,
  `answerable` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=可答（有标准出处），0=不可答（应拒答）',
  `gold_doc` varchar(200) DEFAULT NULL COMMENT '标准答案所在文档名（answerable=1 必填）',
  `gold_section` int DEFAULT NULL COMMENT '标准答案所在段号（可选，段落级 recall 用）',
  `gold_keywords` varchar(500) DEFAULT NULL COMMENT '答案必须命中的关键词，用 | 分隔（引用/正确性校验用）',
  `note` varchar(200) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rag_eval_course` (`course_id`,`answerable`)
) ENGINE=InnoDB AUTO_INCREMENT=169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='RAG 检索评测集';
/*!40101 SET character_set_client = @saved_cs_client */;

