CREATE TABLE `ai_rag_eval_run` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `mode` varchar(16) NOT NULL COMMENT 'FULLTEXT / VECTOR / HYBRID',
  `k` int NOT NULL DEFAULT '4',
  `cases` int NOT NULL DEFAULT '0',
  `recall_at_k` decimal(6,4) DEFAULT NULL,
  `mrr` decimal(6,4) DEFAULT NULL,
  `ndcg_at_k` decimal(6,4) DEFAULT NULL,
  `refuse_acc` decimal(6,4) DEFAULT NULL COMMENT '不可答问题被正确拒答的比例',
  `false_refuse` decimal(6,4) DEFAULT NULL COMMENT '可答问题被误拒的比例',
  `avg_ms` int DEFAULT NULL,
  `detail_json` json DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_rag_eval_mode` (`mode`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='RAG 检索评测结果（三行对比表的数据源）';
