CREATE TABLE `ai_run` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '运行ID',
  `scene` varchar(30) NOT NULL COMMENT '场景：REPORT / QUESTION_GEN / DRAFT_GRADE / QA',
  `target_type` varchar(30) DEFAULT NULL COMMENT '对象类型：ENROLLMENT / TEACHING_CLASS / RESOURCE',
  `target_id` bigint DEFAULT NULL COMMENT '对象ID',
  `status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING / RUNNING / SUCCESS / FAILED / FALLBACK',
  `source` varchar(20) DEFAULT NULL COMMENT 'DIFY / TEMPLATE',
  `model` varchar(50) DEFAULT NULL COMMENT '模型名',
  `app_id` varchar(64) DEFAULT NULL COMMENT 'Dify 应用ID',
  `prompt_version` varchar(20) DEFAULT NULL COMMENT '提示词/工作流版本',
  `total_tokens` int DEFAULT NULL COMMENT '总 token',
  `total_cost` decimal(10,6) DEFAULT NULL COMMENT '估算费用（元）',
  `operator_id` bigint DEFAULT NULL COMMENT '触发人',
  `error_message` varchar(500) DEFAULT NULL COMMENT '失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `finish_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_scene_time` (`scene`,`create_time`),
  KEY `idx_target` (`target_type`,`target_id`)
) ENGINE=InnoDB AUTO_INCREMENT=210 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 运行主记录';
