--
-- Table structure for table `ai_run_step`
--

DROP TABLE IF EXISTS `ai_run_step`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_run_step` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `step_no` int NOT NULL DEFAULT '1',
  `name` varchar(50) NOT NULL COMMENT '步骤名',
  `input_digest` varchar(500) DEFAULT NULL COMMENT '输入摘要',
  `output_digest` varchar(500) DEFAULT NULL COMMENT '输出摘要',
  `validation_status` varchar(20) DEFAULT NULL COMMENT 'PASS / WARN / FAIL',
  `validation_detail` varchar(500) DEFAULT NULL,
  `duration_ms` int DEFAULT NULL,
  `error` varchar(500) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_run` (`run_id`)
) ENGINE=InnoDB AUTO_INCREMENT=264 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 步级明细';
/*!40101 SET character_set_client = @saved_cs_client */;

