--
-- Table structure for table `alert_flow_log`
--

DROP TABLE IF EXISTS `alert_flow_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `alert_flow_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `alert_id` bigint NOT NULL COMMENT '预警ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `event_type` varchar(30) NOT NULL COMMENT '事件：CREATED生成/LEVEL_UP升级/LEVEL_DOWN降级/NOTIFIED已通知/ACKNOWLEDGED已知悉/HANDLED已处理/CLOSED关闭/DISMISSED忽略/EXPIRED超时/ESCALATED已升级上报/REFERRED上报教务/ADMIN_HANDLED教务处理/TERMINATED终止干预/REOPENED重新打开/VOIDED作废',
  `from_level` varchar(10) DEFAULT NULL COMMENT '变更前等级',
  `to_level` varchar(10) DEFAULT NULL COMMENT '变更后等级',
  `from_status` varchar(20) DEFAULT NULL COMMENT '变更前状态',
  `to_status` varchar(20) DEFAULT NULL COMMENT '变更后状态',
  `detail` varchar(500) DEFAULT NULL COMMENT '事件说明（如"缺课达 11 次，触发 1/3 硬门槛"）',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID（系统触发为空）',
  `operator_role` varchar(20) DEFAULT NULL COMMENT '操作人角色：TEACHER/COUNSELOR/ADMIN/SYSTEM',
  `event_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '事件时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_alert_time` (`alert_id`,`event_time`),
  KEY `idx_student_time` (`student_id`,`event_time`),
  KEY `idx_event_type` (`event_type`),
  KEY `idx_event_time` (`event_time`)
) ENGINE=InnoDB AUTO_INCREMENT=4789 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='预警生命周期时间线（替代快照曲线）';
/*!40101 SET character_set_client = @saved_cs_client */;

