CREATE TABLE `alert_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预警ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `enrollment_id` bigint NOT NULL COMMENT '选课ID',
  `offering_id` bigint NOT NULL COMMENT '开课ID',
  `teaching_class_id` bigint NOT NULL COMMENT '教学班ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `alert_level` varchar(10) NOT NULL COMMENT '预警等级：RED/ORANGE/YELLOW',
  `trigger_channel` varchar(10) NOT NULL COMMENT '触发通道：A确定性/B班内相对/C跨班可比',
  `trigger_rule` varchar(50) DEFAULT NULL COMMENT '触发规则：A_HARD_LINE已超1/3/A_NEAR_LINE剩一次/A_UNREACHABLE期末不可达/B_RANK班内靠前/C_THRESHOLD跨班超标',
  `risk_score` decimal(5,1) DEFAULT NULL COMMENT '触发时风险分',
  `confidence` decimal(4,3) DEFAULT NULL COMMENT '触发时置信度',
  `output_mode` varchar(20) DEFAULT NULL COMMENT '触发时输出形态：FULL_SCORE/SCORE_WITH_NOTE/BEHAVIOR_ONLY/INSUFFICIENT',
  `alert_reason` text COMMENT '人话版预警原因（面向老师/学生）',
  `evidence_json` json DEFAULT NULL COMMENT '触发依据快照：{"absent":9,"allowed":10,"remaining":1,"needFinal":93.8,"coverage":0.72}',
  `channel_snapshot_json` json DEFAULT NULL COMMENT '触发时三通道值快照：{"a":"DANGER","b":68.2,"c":null}',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE处理中/ACKNOWLEDGED已知悉/HANDLING处理中/CLOSED已关闭/DISMISSED已忽略/EXPIRED超时关闭',
  `is_current` tinyint(1) DEFAULT NULL COMMENT '是否当前生效预警：1当前 / NULL历史（配合唯一键保证每生每课仅一条当前预警）',
  `escalated` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已升级过等级',
  `escalated_at` datetime DEFAULT NULL COMMENT '升级时间',
  `previous_level` varchar(10) DEFAULT NULL COMMENT '升级前等级',
  `notified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已发出通知',
  `first_notify_time` datetime DEFAULT NULL COMMENT '首次通知时间',
  `expire_time` datetime DEFAULT NULL COMMENT '超时时间（超时未处理 → 自动升级/关闭）',
  `handle_by` bigint DEFAULT NULL COMMENT '处理人ID',
  `handle_role` varchar(20) DEFAULT NULL COMMENT '处理人角色：TEACHER/COUNSELOR/ADMIN',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handle_note` text COMMENT '处理说明',
  `close_by` bigint DEFAULT NULL COMMENT '关闭人ID',
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `close_note` varchar(500) DEFAULT NULL COMMENT '关闭说明/结论',
  `dismiss_reason` varchar(200) DEFAULT NULL COMMENT '忽略原因',
  `student_response` text COMMENT '学生回应（学生端可回执）',
  `student_response_time` datetime DEFAULT NULL COMMENT '学生回应时间',
  `teacher_reply` varchar(500) DEFAULT NULL COMMENT '教师对申诉的回复',
  `teacher_reply_time` datetime DEFAULT NULL COMMENT '教师回复时间',
  `engine_version` varchar(20) DEFAULT NULL COMMENT '产生该预警的引擎版本',
  `is_void` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否作废（退课/重算）：1作废，不进任何统计与列表',
  `void_reason` varchar(200) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enroll_current` (`enrollment_id`,`is_current`),
  KEY `idx_student_status` (`student_id`,`status`,`is_void`),
  KEY `idx_teacher_query` (`teaching_class_id`,`status`),
  KEY `idx_offering_level` (`offering_id`,`alert_level`),
  KEY `idx_term_level` (`term_id`,`alert_level`),
  KEY `idx_status_expire` (`status`,`expire_time`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=3832 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='预警记录表（重建：带通道/置信度/引擎版本）';
/*!40101 SET character_set_client = @saved_cs_client */;

