--
-- Table structure for table `attendance_archive`
--

DROP TABLE IF EXISTS `attendance_archive`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendance_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '归档批次ID',
  `offering_id` bigint NOT NULL COMMENT '开课ID',
  `teaching_class_id` bigint DEFAULT NULL COMMENT '教学班ID（老师按教学班提交；教务按课程汇总查看）',
  `teacher_id` bigint DEFAULT NULL COMMENT '提交老师ID',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `phase` varchar(20) NOT NULL COMMENT '归档阶段：MID期中/FINAL期末',
  `window_open_time` datetime DEFAULT NULL COMMENT '归档窗口开启时间',
  `deadline` datetime DEFAULT NULL COMMENT '提交截止时间',
  `submit_time` datetime DEFAULT NULL COMMENT '老师提交时间',
  `submit_by` bigint DEFAULT NULL COMMENT '提交人（教师ID）',
  `submit_note` varchar(200) DEFAULT NULL COMMENT '提交说明',
  `session_from` int DEFAULT NULL COMMENT '本次归档覆盖的起始课次序号',
  `session_to` int DEFAULT NULL COMMENT '本次归档覆盖的结束课次序号',
  `session_count` int NOT NULL DEFAULT '0' COMMENT '本次归档覆盖课次数',
  `record_count` int NOT NULL DEFAULT '0' COMMENT '本次归档涉及考勤记录条数',
  `coverage_rate` decimal(5,2) DEFAULT NULL COMMENT '提交时的点名覆盖率(%)：已点名课次/应完成课次',
  `status` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT '状态：PENDING待提交/SUBMITTED已提交待审核/REVIEWED已确认/RETURNED已退回',
  `review_by` bigint DEFAULT NULL COMMENT '审核人（教务ID）',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `review_note` varchar(200) DEFAULT NULL COMMENT '审核意见',
  `return_by` bigint DEFAULT NULL COMMENT '退回操作人（教务ID）',
  `return_time` datetime DEFAULT NULL COMMENT '退回时间',
  `return_reason` varchar(200) DEFAULT NULL COMMENT '退回原因',
  `remind_count` int NOT NULL DEFAULT '0' COMMENT '催办次数（未提交时红点+站内信催办）',
  `last_remind_time` datetime DEFAULT NULL COMMENT '最近催办时间',
  `is_void` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否作废（重开批次等）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_phase` (`teaching_class_id`,`phase`,`is_void`),
  KEY `idx_offering_phase` (`offering_id`,`phase`),
  KEY `idx_teacher_status` (`teacher_id`,`status`),
  KEY `idx_status_deadline` (`status`,`deadline`),
  KEY `idx_term_phase` (`term_id`,`phase`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='考勤归档批次表（期中/期末，双轨制的落点）';
/*!40101 SET character_set_client = @saved_cs_client */;

