--
-- Table structure for table `attendance_record_log`
--

DROP TABLE IF EXISTS `attendance_record_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendance_record_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `record_id` bigint NOT NULL COMMENT '考勤记录ID',
  `enrollment_id` bigint NOT NULL COMMENT '选课ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `session_id` bigint NOT NULL COMMENT '课次ID',
  `old_status` varchar(20) DEFAULT NULL COMMENT '变更前状态',
  `new_status` varchar(20) DEFAULT NULL COMMENT '变更后状态',
  `old_phase` varchar(20) DEFAULT NULL COMMENT '变更前口径（NORMAL/ARCHIVE）',
  `new_phase` varchar(20) DEFAULT NULL COMMENT '变更后口径',
  `change_type` varchar(30) NOT NULL COMMENT '变更类型：TEACHER_INPUT老师首次录入/TEACHER_EDIT老师平时修改/ARCHIVE_CONFIRM归档确认/ADMIN_CORRECT归档后教务更正/VOID作废/RESTORE恢复',
  `reason` varchar(200) DEFAULT NULL COMMENT '变更原因',
  `changed_by` bigint DEFAULT NULL COMMENT '操作人ID',
  `changed_role` varchar(20) DEFAULT NULL COMMENT '操作人角色：TEACHER/ADMIN',
  `changed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '变更时间',
  `batch_key` varchar(40) DEFAULT NULL COMMENT '关联批次号',
  PRIMARY KEY (`id`),
  KEY `idx_record` (`record_id`),
  KEY `idx_student` (`student_id`,`changed_at`),
  KEY `idx_session` (`session_id`),
  KEY `idx_change_type` (`change_type`),
  KEY `idx_changed_at` (`changed_at`)
) ENGINE=InnoDB AUTO_INCREMENT=590 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='考勤改动留痕表（行级 before/after）';
/*!40101 SET character_set_client = @saved_cs_client */;

