--
-- Table structure for table `audit_log`
--

DROP TABLE IF EXISTS `audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `biz_type` varchar(30) NOT NULL COMMENT '业务类型：SCORE成绩/ATTENDANCE考勤/ARCHIVE归档/REFER上报/INTERVENTION干预/COURSE_GROUP课程组/SCORE_SCHEME成绩构成/OFFERING开课/ACTUAL_SESSIONS实际课次/EXAM_HEADCOUNT考核人数/ACCOUNT账号/NOTIFICATION通知/IMPORT导入/QUESTIONNAIRE问卷/SYSTEM系统',
  `biz_id` bigint DEFAULT NULL COMMENT '业务对象ID',
  `action` varchar(30) NOT NULL COMMENT '动作：CREATE/UPDATE/DELETE/VOID/RESTORE/LOCK/UNLOCK/CONFIRM/APPROVE/REJECT/SUBMIT/RETURN/REFER/TERMINATE/IMPORT/ROLLBACK/LOGIN/PASSWORD_RESET',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_role` varchar(20) DEFAULT NULL COMMENT '操作人角色：STUDENT/TEACHER/COUNSELOR/ADMIN/SYSTEM',
  `before_json` json DEFAULT NULL COMMENT '变更前快照（敏感字段脱敏，如密码只记是否变更）',
  `after_json` json DEFAULT NULL COMMENT '变更后快照',
  `detail` varchar(500) DEFAULT NULL COMMENT '说明（人可读）',
  `ip` varchar(45) DEFAULT NULL COMMENT '来源IP',
  `user_agent` varchar(200) DEFAULT NULL COMMENT '客户端信息（可选）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发生时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz` (`biz_type`,`biz_id`),
  KEY `idx_operator_time` (`operator_id`,`create_time`),
  KEY `idx_action_time` (`action`,`create_time`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=1034 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='统一审计日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

