DROP TABLE IF EXISTS `course`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '课程ID（科目）',
  `course_name` varchar(50) NOT NULL COMMENT '课程名称',
  `course_type` varchar(20) NOT NULL DEFAULT 'EXAM' COMMENT '课程类型：只分两类 —— EXAM考试课 / ASSESS考查课（上机/卷面、个人/团队项目等差异不单独分类，改由 difficulty_factor_code 指向课型难度因子档位）',
  `credit` decimal(3,1) DEFAULT NULL COMMENT '学分',
  `total_hours` int DEFAULT NULL COMMENT '计划学时（展示用；课次口径以开课为准）',
  `prerequisite_course_id` bigint DEFAULT NULL COMMENT '先修课程ID（同科目序列，如 高数1→高数2→高数3）',
  `college_name` varchar(50) DEFAULT NULL COMMENT '开课学院',
  `difficulty_factor_code` varchar(30) DEFAULT NULL COMMENT '课型难度因子档位编码（教务按课指定，如 PAPER卷面/MACHINE上机/PERSONAL个人项目/TEAM团队项目/OTHER；留空则用所属 course_type 的默认档）。档位与数值定义在 risk_engine_config.course_type_factor_json，可随时增档而不用改建表',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE/CLOSED停开',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_course_type` (`course_type`),
  KEY `idx_difficulty` (`difficulty_factor_code`),
  KEY `idx_prerequisite` (`prerequisite_course_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='课程（科目）表';
