  `level_request_reason` varchar(200) DEFAULT NULL COMMENT '申请理由（如：本课含 5 次实验 + 三级项目）',
  `level_approve_by` bigint DEFAULT NULL COMMENT '审批人（教务ID）',
  `level_approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `level_approve_note` varchar(200) DEFAULT NULL COMMENT '审批意见',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE/CLOSED',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
