--
-- Table structure for table `import_batch`
--

DROP TABLE IF EXISTS `import_batch`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `import_batch` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `batch_no` varchar(40) NOT NULL COMMENT '批次号（业务表按此回滚）',
  `import_type` varchar(30) NOT NULL COMMENT '类型：TIMETABLE周数课次/SCORE成绩/ATTENDANCE考勤/ROSTER名单/PAPER试卷题目/OTHER（已移除 KP）',
  `term_id` bigint DEFAULT NULL COMMENT '学期ID（部分导入与学期无关，可空）',
  `file_name` varchar(200) DEFAULT NULL COMMENT '原始文件名',
  `total_rows` int NOT NULL DEFAULT '0' COMMENT '总行数',
  `success_rows` int NOT NULL DEFAULT '0' COMMENT '成功行数',
  `failed_rows` int NOT NULL DEFAULT '0' COMMENT '失败行数',
  `error_json` json DEFAULT NULL COMMENT '失败明细（行号 + 原因）',
  `status` varchar(20) NOT NULL DEFAULT 'RUNNING' COMMENT '状态：RUNNING进行中/SUCCESS全部成功/PARTIAL部分成功/FAILED失败/ROLLED_BACK已回滚',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_role` varchar(20) DEFAULT NULL COMMENT '操作人角色',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `rollback_by` bigint DEFAULT NULL COMMENT '回滚人',
  `rollback_time` datetime DEFAULT NULL COMMENT '回滚时间',
  `rollback_reason` varchar(200) DEFAULT NULL COMMENT '回滚原因',
  `remark` varchar(200) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_no` (`batch_no`),
  KEY `idx_type_time` (`import_type`,`create_time`),
  KEY `idx_status` (`status`),
  KEY `idx_operator` (`operator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='导入批次表（可查可回滚）';
/*!40101 SET character_set_client = @saved_cs_client */;

