--
-- Table structure for table `intervention_record`
--

DROP TABLE IF EXISTS `intervention_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `intervention_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '干预记录ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `term_id` bigint DEFAULT NULL COMMENT '学期ID（旧数据迁移时可为空）',
  `alert_id` bigint DEFAULT NULL COMMENT '关联预警ID（可空：可由教师主动发起，不只针对单条预警）',
  `related_alert_ids` json DEFAULT NULL COMMENT '关联预警ID数组（一次处理可覆盖多条预警）',
  `stage` varchar(30) NOT NULL COMMENT '阶段：TEACHER教师处理/COUNSELOR_1导员第1次/COUNSELOR_2导员第2次/REFERRED已上报教务/ADMIN_TALK教务面谈/ADMIN_HELP教务具体帮助/TERMINATED终止干预',
  `operator_id` bigint NOT NULL COMMENT '处理人ID',
  `operator_role` varchar(20) NOT NULL COMMENT '处理人角色：TEACHER/COUNSELOR/ADMIN',
  `action_type` varchar(30) NOT NULL COMMENT '动作：TALK谈话/CLASS_MEETING班会/PARENT联系家长/SUPPLEMENT补课补习/PLAN学习计划/INTERVIEW面谈/HELP具体帮助/OTHER其他',
  `content` text COMMENT '处理内容',
  `result` text COMMENT '结果描述',
  `effective` varchar(20) NOT NULL DEFAULT 'PENDING' COMMENT '是否有成效：EFFECTIVE有效/INEFFECTIVE无效/PENDING待观察',
  `effect_check_time` datetime DEFAULT NULL COMMENT '成效检查时间（= 下次 risk_state 刷新 或 干预后 14 天，先到为准）',
  `risk_score_before` decimal(5,1) DEFAULT NULL COMMENT '干预时风险分（快照）',
  `risk_score_after` decimal(5,1) DEFAULT NULL COMMENT '成效检查时的风险分',
  `risk_score_change` decimal(5,1) DEFAULT NULL COMMENT '风险分变化（负数=改善）',
  `refer_status` varchar(20) DEFAULT NULL COMMENT '上报状态：NONE未上报/REFERRED已上报/ADMIN_HANDLING教务处理中/ADMIN_DONE教务已完结',
  `refer_by` bigint DEFAULT NULL COMMENT '上报人（导员ID）',
  `refer_time` datetime DEFAULT NULL COMMENT '上报时间',
  `refer_note` varchar(500) DEFAULT NULL COMMENT '上报说明（导员判定"收集齐全"的说明）',
  `admin_feedback` text COMMENT '教务处理反馈（导员可追踪"交上去之后怎么样了"）',
  `is_void` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否作废',
  `remark` varchar(200) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_student_time` (`student_id`,`create_time`),
  KEY `idx_alert` (`alert_id`),
  KEY `idx_operator` (`operator_id`,`operator_role`),
  KEY `idx_stage` (`stage`),
  KEY `idx_effective` (`effective`,`effect_check_time`),
  KEY `idx_refer` (`refer_status`)
) ENGINE=InnoDB AUTO_INCREMENT=3332 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='干预记录表（重构：支持教师/导员/教务三级与上报闭环）';
/*!40101 SET character_set_client = @saved_cs_client */;

