-- Table structure for table `notification`
--

DROP TABLE IF EXISTS `notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '通知ID',
  `biz_type` varchar(30) NOT NULL COMMENT '业务类型：ALERT_NEW/ALERT_UPGRADE/CLASS_ALERT班集体提醒/ARCHIVE_TASK归档待办/ARCHIVE_RESULT归档结果/COVERAGE_REMIND覆盖率提醒/SCORE_TASK打分待办/MULTI_COURSE多科目预警/REFER_RESULT上报结果/QUESTIONNAIRE问卷/SYSTEM系统',
  `biz_id` bigint DEFAULT NULL COMMENT '关联业务ID（预警/归档批次/开课/问卷等）',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `content` text COMMENT '正文',
  `payload_json` json DEFAULT NULL COMMENT '结构化载荷（跳转参数、明细列表等）',
  `aggregate_key` varchar(60) DEFAULT NULL COMMENT '聚合键：如 CLASS_ALERT:{counselorId}:{termId}:{weekNo}，同键只发一条汇总',
  `aggregate_count` int NOT NULL DEFAULT '1' COMMENT '本通知聚合了多少条明细（防骚扰：一次一条汇总）',
  `audience_desc` varchar(100) DEFAULT NULL COMMENT '接收范围描述，如"软件1–4班导员 + 教务处"',
  `priority` varchar(10) NOT NULL DEFAULT 'NORMAL' COMMENT '优先级：HIGH/NORMAL/LOW',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_aggregate_key` (`aggregate_key`),
  KEY `idx_biz` (`biz_type`,`biz_id`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=9805 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='通知主体表（聚合与业务关联）';
/*!40101 SET character_set_client = @saved_cs_client */;

