UNLOCK TABLES;

--
-- Table structure for table `project_submission`
--

DROP TABLE IF EXISTS `project_submission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project_submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `project_id` bigint NOT NULL COMMENT '项目任务ID',
  `team_id` bigint DEFAULT NULL COMMENT '组ID（个人项目为空）',
  `student_id` bigint NOT NULL COMMENT '提交人（团队项目=组长）',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `files_json` json DEFAULT NULL COMMENT '提交文件列表',
  `repo_url` varchar(500) DEFAULT NULL COMMENT '代码仓库链接（可选）',
  `remark` varchar(500) DEFAULT NULL COMMENT '提交说明',
  `submit_status` varchar(20) NOT NULL DEFAULT 'NOT_SUBMITTED' COMMENT '状态：NOT_SUBMITTED未提交/SUBMITTED已提交/MARKED已批阅',
