  KEY `idx_status` (`submit_status`)
) ENGINE=InnoDB AUTO_INCREMENT=36307 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='项目提交与批阅表';
