--
-- Table structure for table `question`
--

DROP TABLE IF EXISTS `question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `question` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `paper_id` bigint NOT NULL COMMENT '试卷ID',
  `q_no` int NOT NULL COMMENT '题号（试卷内序号）',
  `q_type` varchar(20) NOT NULL COMMENT '题型：SINGLE单选/MULTI多选/JUDGE判断/BLANK填空/SHORT简答',
  `stem` text NOT NULL COMMENT '题干',
  `options_json` json DEFAULT NULL COMMENT '选项（选择题使用）',
  `answer_json` json DEFAULT NULL COMMENT '标准答案（结构见上）',
  `analysis` text COMMENT '解析（学生端是否可见取决于 paper.show_answer）',
  `full_score` decimal(6,2) NOT NULL COMMENT '本题分值',
  `group_name` varchar(100) DEFAULT NULL COMMENT '大题名称（如“第一大题 单选题”），用于学生端分组展示',
  `sort_no` int NOT NULL DEFAULT '1' COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_paper_sort` (`paper_id`,`sort_no`)
) ENGINE=InnoDB AUTO_INCREMENT=21285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='题目表';
/*!40101 SET character_set_client = @saved_cs_client */;

