/*!40000 ALTER TABLE `questionnaire` DISABLE KEYS */;
INSERT INTO `questionnaire` VALUES (1,101,1,5,'TEACHER_STYLE','2026-2027-1 教师风格判定（大学计算机基础）','[{\"q\": \"该教师讲课节奏是否合适\", \"type\": \"SCALE\", \"itemCode\": \"Q1\"}, {\"q\": \"作业量是否合理\", \"type\": \"SCALE\", \"itemCode\": \"Q2\"}, {\"q\": \"给分是否严格\", \"type\": \"SCALE\", \"itemCode\": \"Q3\"}, {\"q\": \"课堂互动是否充分\", \"type\": \"SCALE\", \"itemCode\": \"Q4\"}, {\"q\": \"整体评价\", \"type\": \"SCALE\", \"itemCode\": \"Q5\"}]',1,'COUNSELOR',1440,'[1, 2]','2026-10-10 09:00:00','2026-12-20 23:59:00','COLLECTING',5,1440,'2026-10-12 10:00:00',1442,'2026-10-14 09:00:00',NULL,1440,'2026-10-10 09:00:00',NULL,'2026-10-18 15:00:00'),(2,101,1,5,'SATISFACTION','2026-2027-1 校园学习生活满意度调查（食堂 / 图书馆 / 宿舍）','[{\"q\": \"食堂饭菜质量与价格\", \"type\": \"SCALE\", \"itemCode\": \"Q1\"}, {\"q\": \"图书馆座位、借阅与自习环境\", \"type\": \"SCALE\", \"itemCode\": \"Q2\"}, {\"q\": \"宿舍环境与生活设施\", \"type\": \"SCALE\", \"itemCode\": \"Q3\"}, {\"q\": \"校园安全与后勤服务\", \"type\": \"SCALE\", \"itemCode\": \"Q4\"}, {\"q\": \"对学校整体满意度\", \"type\": \"SCALE\", \"itemCode\": \"Q5\"}, {\"q\": \"最希望学校改进的一项（选填）\", \"type\": \"TEXT\", \"itemCode\": \"Q6\"}]',1,'ADMIN',1442,'[1, 2]','2026-10-20 09:00:00','2026-12-31 23:59:00','COLLECTING',0,NULL,NULL,NULL,NULL,NULL,1442,'2026-10-20 09:00:00',NULL,'2026-10-26 19:56:04'),(3,101,1,5,'MENTAL_HEALTH','2026 年秋季学生心理健康普查（匿名）','[{\"q\": \"最近两周整体情绪状态\", \"type\": \"SCALE\", \"itemCode\": \"Q1\"}, {\"q\": \"最近两周睡眠质量\", \"type\": \"SCALE\", \"itemCode\": \"Q2\"}, {\"q\": \"学业压力感受\", \"type\": \"SCALE\", \"itemCode\": \"Q3\"}, {\"q\": \"与同学、室友的人际关系\", \"type\": \"SCALE\", \"itemCode\": \"Q4\"}, {\"q\": \"其他想说明的情况（选填）\", \"type\": \"TEXT\", \"itemCode\": \"Q5\"}]',1,'COUNSELOR',1440,'[1, 2]','2026-10-22 09:00:00','2026-12-31 23:59:00','COLLECTING',0,NULL,NULL,NULL,NULL,NULL,1440,'2026-10-22 09:00:00',NULL,'2026-10-26 19:56:04'),(4,101,1,5,'NATIONAL_SURVEY','2026 年全国本科生学情调查（本校问卷）','[{\"q\": \"每周课外学习时间投入\", \"type\": \"SCALE\", \"itemCode\": \"Q1\"}, {\"q\": \"课程挑战度\", \"type\": \"SCALE\", \"itemCode\": \"Q2\"}, {\"q\": \"与教师的互动频率\", \"type\": \"SCALE\", \"itemCode\": \"Q3\"}, {\"q\": \"本学期学习收获自评\", \"type\": \"SCALE\", \"itemCode\": \"Q4\"}, {\"q\": \"对学校教学的建议（选填）\", \"type\": \"TEXT\", \"itemCode\": \"Q5\"}]',1,'ADMIN',1442,'[1, 2]','2026-10-22 09:00:00','2026-12-31 23:59:00','COLLECTING',0,NULL,NULL,NULL,NULL,NULL,1442,'2026-10-22 09:00:00',NULL,'2026-10-22 09:00:00'),(5,104,7,5,'GRADUATE_SURVEY','2027 届毕业生去向与就业调研（2024 级）','[{\"q\": \"毕业去向的明确程度\", \"type\": \"SCALE\", \"itemCode\": \"Q1\"}, {\"q\": \"目前落实去向的进展\", \"type\": \"SCALE\", \"itemCode\": \"Q2\"}, {\"q\": \"对学校就业指导的满意度\", \"type\": \"SCALE\", \"itemCode\": \"Q3\"}, {\"q\": \"专业课程对求职的帮助\", \"type\": \"SCALE\", \"itemCode\": \"Q4\"}, {\"q\": \"计划去向（升学 / 就业 / 考公 / 创业 / 其他，选填）\", \"type\": \"TEXT\", \"itemCode\": \"Q5\"}]',1,'COUNSELOR',1440,'[3]','2026-10-22 09:00:00','2026-12-31 23:59:00','COLLECTING',0,NULL,NULL,NULL,NULL,NULL,1440,'2026-10-22 09:00:00',NULL,'2026-10-22 09:00:00');
