  KEY `idx_q_teacher` (`questionnaire_id`,`target_teacher_id`),
  KEY `idx_student` (`student_id`)
) ENGINE=InnoDB AUTO_INCREMENT=8036 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='问卷作答明细表（匿名去重）';
