  `void_reason` varchar(200) DEFAULT NULL COMMENT '作废原因',
  PRIMARY KEY (`id`),
  KEY `idx_tc` (`teaching_class_id`),
  KEY `idx_upload` (`upload_by`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='资源文件表（课程资料库）';
