--
-- Table structure for table `risk_state`
--

DROP TABLE IF EXISTS `risk_state`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `risk_state` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `enrollment_id` bigint NOT NULL COMMENT '选课ID（一人一课一行）',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `offering_id` bigint NOT NULL COMMENT '开课ID',
  `teaching_class_id` bigint NOT NULL COMMENT '教学班ID',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `absent_count` int NOT NULL DEFAULT '0' COMMENT 'A通道：当前累计缺课次数',
  `late_count` int NOT NULL DEFAULT '0' COMMENT 'A通道：当前累计迟到次数',
  `leave_count` int NOT NULL DEFAULT '0' COMMENT 'A通道：当前累计请假次数',
  `allowed_absent` int DEFAULT NULL COMMENT 'A通道：允许缺课上限 N_max = floor(分母课次/3)',
  `remaining_absent` int DEFAULT NULL COMMENT 'A通道：剩余可缺次数 = N_max − 已缺；0=再缺一次即挂；≤−1=必然挂科',
  `hard_fail` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'A通道：是否已触发 1/3 硬门槛',
  `near_fail` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'A通道：是否高危（剩余可缺 ≤ 1）',
  `final_exam_needed` decimal(6,1) DEFAULT NULL COMMENT 'A通道：期末需考分数 x = (pass_score + P − W_其余项)/r_f',
  `final_unreachable` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'A通道：x > 期末满分 → 实际不可达',
  `channel_a_level` varchar(20) DEFAULT NULL COMMENT 'A通道等级：SAFE正常/WATCH警戒/DANGER再缺一次即挂/FAIL必然挂科',
  `channel_b_score` decimal(5,2) DEFAULT NULL COMMENT 'B通道：班内相对风险分（0–100）',
  `channel_b_rank` int DEFAULT NULL COMMENT 'B通道：班内风险排名（1 最危险）',
  `channel_b_class_size` int DEFAULT NULL COMMENT 'B通道：同班人数',
  `channel_b_level` varchar(20) DEFAULT NULL COMMENT 'B通道等级：SAME_AS_A 语义不混算，仅作分档展示',
  `channel_c_score` decimal(6,2) DEFAULT NULL COMMENT 'C通道：折算后的跨班可比风险分（影子分数，不落成绩表）',
  `delta_used` decimal(5,2) DEFAULT NULL COMMENT 'C通道：本次使用的教师尺度 Δ̂（收缩后）',
  `course_factor_used` decimal(5,3) DEFAULT NULL COMMENT 'C通道：本次使用的课程因子 c',
  `channel_c_level` varchar(20) DEFAULT NULL COMMENT 'C通道等级：RED/ORANGE/YELLOW/GREEN（按 engine 阈值分档）',
  `risk_score` decimal(5,1) DEFAULT NULL COMMENT '当前对外风险分（有 C 用 C，无 C 用 B，A 单列展示）',
  `risk_level` varchar(10) DEFAULT NULL COMMENT '当前等级：RED/ORANGE/YELLOW/GREEN',
  `active_channel` varchar(10) DEFAULT NULL COMMENT '当前生效通道：A/B/C（教务看C、导员看A+B）',
  `confidence` decimal(4,3) DEFAULT NULL COMMENT '置信度 W = 锚点强度 × 数据完备度 × 样本充足度（0–1）',
  `confidence_level` varchar(20) DEFAULT NULL COMMENT '置信度档：HIGH/MEDIUM/LOW/VERY_LOW',
  `output_mode` varchar(20) DEFAULT NULL COMMENT '输出形态：FULL_SCORE完整分档/SCORE_WITH_NOTE带标注/BEHAVIOR_ONLY仅行为预警/INSUFFICIENT数据不足',
  `data_quality_json` json DEFAULT NULL COMMENT '数据质量明细：{"coverage":0.62,"anchorStrength":0.8,"sampleSize":120,"attendanceSourceMix":"NORMAL","missing":["mid_score"]}',
  `trigger_source` varchar(20) DEFAULT NULL COMMENT '本次刷新来源：EVALUATION评估/DATA_CHANGE数据变更/MANUAL人工/WITHDRAW退课作废',
  `last_eval_time` datetime DEFAULT NULL COMMENT '最近一次刷新时间（干预"无效判定"以此为窗口起点之一）',
  `engine_version` varchar(20) DEFAULT NULL COMMENT '计算所用引擎版本',
  `is_void` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否作废（退课/重算）：1作废，不进任何统计与列表',
  `void_reason` varchar(200) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enrollment` (`enrollment_id`),
  KEY `idx_student_void` (`student_id`,`is_void`),
  KEY `idx_offering_level` (`offering_id`,`risk_level`),
  KEY `idx_class_level` (`teaching_class_id`,`risk_level`),
  KEY `idx_term_level` (`term_id`,`risk_level`),
  KEY `idx_eval_time` (`last_eval_time`)
) ENGINE=InnoDB AUTO_INCREMENT=11403 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='当前风险状态表（替代每日快照；一人一课一行）';
/*!40101 SET character_set_client = @saved_cs_client */;

