INSERT INTO `score_template` VALUES (1,'EXAM_DEFAULT','考试课默认构成','EXAM','L2','[{\"code\": \"USUAL\", \"name\": \"平时\", \"weight\": 40, \"children\": [{\"code\": \"HW\", \"name\": \"课后作业\", \"weight\": 40, \"dataSource\": \"AUTO\", \"aggregateMode\": \"AVG\", \"expectedTimes\": 9}, {\"code\": \"QUIZ\", \"name\": \"课堂测试\", \"weight\": 30, \"dataSource\": \"MANUAL\", \"aggregateMode\": \"AVG\", \"expectedTimes\": 3}, {\"code\": \"PERF\", \"name\": \"课堂表现\", \"weight\": 15, \"dataSource\": \"MANUAL\", \"isSubjective\": true}, {\"code\": \"EXP\", \"name\": \"实验报告\", \"weight\": 15, \"dataSource\": \"MANUAL\", \"aggregateMode\": \"AVG\", \"expectedTimes\": 5}]}, {\"code\": \"MID\", \"name\": \"期中\", \"weight\": 20, \"children\": [{\"code\": \"MID_EXAM\", \"name\": \"期中考试\", \"weight\": 100, \"isAnchor\": true, \"dataSource\": \"MANUAL\", \"anchorLayer\": \"A\"}]}, {\"code\": \"FINAL\", \"name\": \"期末\", \"weight\": 40, \"children\": [{\"code\": \"FINAL_EXAM\", \"name\": \"期末闭卷\", \"weight\": 100, \"isAnchor\": true, \"dataSource\": \"MANUAL\", \"anchorLayer\": \"A\"}]}]','考试课：平时40 + 期中20 + 期末40；平时含作业/测试/表现/实验',1,'ACTIVE',NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(2,'ASSESS_DEFAULT','考查课默认构成','ASSESS','L2','[{\"code\": \"USUAL\", \"name\": \"平时\", \"weight\": 60, \"children\": [{\"code\": \"HW\", \"name\": \"课后作业\", \"weight\": 40, \"dataSource\": \"AUTO\", \"aggregateMode\": \"AVG\", \"expectedTimes\": 9}, {\"code\": \"QUIZ\", \"name\": \"课堂测试\", \"weight\": 30, \"dataSource\": \"MANUAL\", \"aggregateMode\": \"AVG\", \"expectedTimes\": 3}, {\"code\": \"PERF\", \"name\": \"课堂表现\", \"weight\": 30, \"dataSource\": \"MANUAL\", \"isSubjective\": true}]}, {\"code\": \"FINAL\", \"name\": \"期末\", \"weight\": 40, \"children\": [{\"code\": \"FINAL_EXAM\", \"name\": \"期末考核\", \"weight\": 100, \"isAnchor\": true, \"dataSource\": \"MANUAL\", \"anchorLayer\": \"A\"}]}]','考查课：平时60 + 期末40（旧库两门课即此类：期中占比为 0）',1,'ACTIVE',NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46');
