DROP TABLE IF EXISTS `student`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '学生ID',
  `account_id` bigint DEFAULT NULL COMMENT '账号ID（迁移期可为空，迁移后应非空）',
  `student_no` varchar(20) NOT NULL COMMENT '学号',
  `student_name` varchar(30) NOT NULL COMMENT '姓名',
  `gender` tinyint(1) DEFAULT NULL COMMENT '性别：1男 2女 0未知',
  `enroll_year` int DEFAULT NULL COMMENT '入学年份，如 2024（年级由此推算，不再存"大一上"这类学期值）',
  `major_id` bigint DEFAULT NULL COMMENT '专业ID（转专业后更新，历史由 audit_log 留痕）',
  `admin_class_id` bigint DEFAULT NULL COMMENT '行政班ID',
  `status` varchar(20) NOT NULL DEFAULT 'IN_SCHOOL' COMMENT '学籍状态：IN_SCHOOL在读/SUSPENDED休学/WITHDRAWN退学/GRADUATED毕业',
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_no` (`student_no`),
  KEY `idx_account` (`account_id`),
  KEY `idx_admin_class` (`admin_class_id`),
  KEY `idx_major` (`major_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1135 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='学生表';
/*!40101 SET character_set_client = @saved_cs_client */;

