--
-- Table structure for table `student_fail_history`
--

DROP TABLE IF EXISTS `student_fail_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_fail_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `offering_id` bigint NOT NULL COMMENT '开课ID',
  `final_score` decimal(6,2) DEFAULT NULL COMMENT '最终总评 T（快照）',
  `pass_score` int DEFAULT NULL COMMENT '及格线（快照）',
  `is_fail` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否挂科',
  `hard_fail` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否因 1/3 硬门槛挂科',
  `is_retake` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否重修记录',
  `score_status` varchar(20) DEFAULT NULL COMMENT '成绩状态（FINAL/DEFERRED_GIVEUP/ABSENT_EXAM…）',
  `engine_version` varchar(20) DEFAULT NULL,
  `archived_at` datetime DEFAULT NULL COMMENT '归档为历史的时间（学期结束结算后写入）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_offering` (`student_id`,`offering_id`),
  KEY `idx_student` (`student_id`,`term_id`),
  KEY `idx_course_term` (`course_id`,`term_id`),
  KEY `idx_fail` (`is_fail`)
) ENGINE=InnoDB AUTO_INCREMENT=7091 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='学生跨学期成绩/挂科历史表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `student_fail_history`
--

