--
-- Table structure for table `submission`
--

DROP TABLE IF EXISTS `submission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `paper_id` bigint NOT NULL COMMENT '试卷ID',
  `teaching_class_id` bigint NOT NULL COMMENT '教学班ID（冗余）',
  `term_id` bigint NOT NULL COMMENT '学期ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `enrollment_id` bigint NOT NULL COMMENT '选课ID（过程数据挂在选课上）',
  `submit_status` varchar(20) NOT NULL DEFAULT 'SUBMITTED' COMMENT '状态：SUBMITTED已交/MARKED已批阅/ABSENT缺考',
  `start_time` datetime DEFAULT NULL COMMENT '开考时间',
  `submit_time` datetime DEFAULT NULL COMMENT '交卷时间',
  `duration_seconds` int DEFAULT NULL COMMENT '答题用时（秒）',
  `objective_score` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '客观题得分（系统判）',
  `subjective_score` decimal(6,2) NOT NULL DEFAULT '0.00' COMMENT '主观题得分（教师判）',
  `total_score` decimal(6,2) DEFAULT NULL COMMENT '总分（批阅完成后写入）',
  `marked_status` varchar(20) NOT NULL DEFAULT 'NOT_MARKED' COMMENT '批阅进度：NOT_MARKED/SYSTEM_MARKED客观已判/ALL_MARKED全部批完',
  `marked_by` bigint DEFAULT NULL COMMENT '最后批阅人（教师ID；系统判分为空）',
  `marked_at` datetime DEFAULT NULL COMMENT '最后批阅时间',
  `is_absent` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否缺考：1是（记 0 分）',
  `remark` varchar(200) DEFAULT NULL COMMENT '整卷批注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_paper_student` (`paper_id`,`student_id`),
  KEY `idx_tc_status` (`teaching_class_id`,`submit_status`),
  KEY `idx_enrollment` (`enrollment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=805584 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='提交与作答记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `submission`
--

