--
-- Table structure for table `submission_answer`
--

DROP TABLE IF EXISTS `submission_answer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `submission_answer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `submission_id` bigint NOT NULL COMMENT '提交记录ID',
  `question_id` bigint NOT NULL COMMENT '题目ID',
  `answer_json` json DEFAULT NULL COMMENT '学生答案（结构同 question.answer_json）',
  `score` decimal(6,2) DEFAULT NULL COMMENT '本题得分',
  `is_correct` tinyint(1) DEFAULT NULL COMMENT '客观题是否正确：1对/0错（主观题为空）',
  `comment` varchar(500) DEFAULT NULL COMMENT '教师批注',
  `marked_by_type` varchar(20) DEFAULT NULL COMMENT '判卷人类型：SYSTEM系统/TEACHER教师/AI智能',
  `marked_by` bigint DEFAULT NULL COMMENT '判卷人ID（教师ID；系统或AI为空）',
  `marked_at` datetime DEFAULT NULL COMMENT '判卷时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sub_q` (`submission_id`,`question_id`),
  KEY `idx_question` (`question_id`)
) ENGINE=InnoDB AUTO_INCREMENT=911175 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='逐题作答与判分表';
/*!40101 SET character_set_client = @saved_cs_client */;

