INSERT INTO `submission_answer` VALUES (900001,800001,21001,'{\"text\": \"因为二进制只有 0 和 1 两个状态，正好对应电路的「导通/截止」，物理上最容易实现，抗干扰能力强；而且加法、乘法规则极简单，可以用逻辑门直接实现。它还能天然对应布尔逻辑的真假，便于用逻辑电路做运算。适合的例子：开关状态、逻辑判断、磁盘磁化方向都可以用两种状态表示；不适合直接表示的例子：十进制小数（0.1 在二进制里是无限循环，只能近似）、汉字与字符（需要额外编码，如 GBK、UTF-8 用多个字节表示）。所以二进制是一种工程折中，实际使用时要配合编码方案与浮点精度设计。\"}',44.00,NULL,NULL,'TEACHER',1431,'2026-11-03 22:24:26','2026-10-10 08:02:00','2026-11-03 22:24:26'),(900002,800001,21002,'{\"text\": \"冯·诺依曼结构由运算器、控制器、存储器、输入设备、输出设备五部分组成。它的核心思想是「存储程序」：把程序指令和数据一起以二进制形式存进存储器，CPU 按程序计数器 PC 给出的地址取指令，译码后执行，再写回结果，然后 PC 自增，如此循环。例如执行一条加法指令时，先按 PC 取指令，再由控制器译码，从存储器取出操作数送运算器相加，结果写回内存或寄存器。它的主要局限是以运算器为中心、指令与数据共用一条总线，形成「冯·诺依曼瓶颈」，并且顺序执行限制了并行度。\"}',46.00,NULL,NULL,'TEACHER',1431,'2026-11-03 22:24:26','2026-10-10 08:02:00','2026-11-03 22:24:26'),(900003,800002,21001,'{\"text\": \"计算机用二进制是因为电路只有通和断两种状态，用 0 和 1 表示比较容易实现，而且运算规则简单。\"}',24.00,NULL,NULL,'TEACHER',1431,'2026-11-03 22:24:27','2026-10-10 08:02:00','2026-11-03 22:24:27'),(900004,800002,21002,'{\"text\": \"冯·诺依曼结构包括运算器、控制器、存储器、输入设备和输出设备五部分，程序和数据都放在存储器里，CPU 按顺序取指令执行。\"}',22.00,NULL,NULL,'TEACHER',1431,'2026-11-03 22:24:28','2026-10-10 08:02:00','2026-11-03 22:24:28'),(900005,800003,21001,'{\"text\": \"因为电路好实现，课本上讲过。\"}',6.00,NULL,NULL,'TEACHER',1431,'2026-11-03 22:24:29','2026-10-10 08:02:00','2026-11-03 22:24:29'),(900006,800003,21002,'{\"text\": \"就是五大部分一起工作，老师上课讲过。\"}',5.00,NULL,NULL,'TEACHER',1431,'2026-11-03 22:24:29','2026-10-10 08:02:00','2026-11-03 22:24:29'),(900007,800004,21001,'{\"text\": \"答：要点见课堂讲解。\"}',42.00,NULL,NULL,'TEACHER',1431,'2026-10-10 23:59:00','2026-10-10 08:02:00','2026-10-10 23:59:00'),(900008,800004,21002,'{\"text\": \"答：补充说明。\"}',43.00,NULL,NULL,'TEACHER',1431,'2026-10-10 23:59:00','2026-10-10 08:02:00','2026-10-10 23:59:00'),(900009,800005,21001,'{\"text\": \"答：要点见课堂讲解。\"}',38.00,NULL,NULL,'TEACHER',1431,'2026-10-10 23:59:00','2026-10-10 08:02:00','2026-10-10 23:59:00'),(900010,800005,21002,'{\"text\": \"答：补充说明。\"}',38.00,NULL,NULL,'TEACHER',1431,'2026-10-