--
-- Table structure for table `sys_account`
--

DROP TABLE IF EXISTS `sys_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '账号ID',
  `login_no` varchar(30) NOT NULL COMMENT '登录号（学号/工号/管理员号，全库唯一）',
  `password_hash` varchar(100) NOT NULL COMMENT '口令哈希：PBKDF2WithHmacSHA256，格式 pbkdf2$迭代次数$Base64(盐)$Base64(哈希)',
  `role` varchar(20) NOT NULL COMMENT '角色：STUDENT/TEACHER/COUNSELOR/ADMIN',
  `real_name` varchar(30) DEFAULT NULL COMMENT '姓名（冗余展示用，可与档案表同步）',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE正常/DISABLED停用/LOCKED锁定',
  `token` varchar(64) DEFAULT NULL COMMENT '当前登录令牌（单点登录）',
  `token_expire_time` datetime DEFAULT NULL COMMENT '令牌过期时间',
  `pwd_update_time` datetime DEFAULT NULL COMMENT '最近改密时间',
  `last_login_time` datetime DEFAULT NULL COMMENT '最近登录时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_login_no` (`login_no`),
  UNIQUE KEY `uk_token` (`token`),
  KEY `idx_role_status` (`role`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2135 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='统一账号表（四端登录）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_account`
--

