INSERT INTO `system_config` VALUES (1,'archive.mid.week','9','INT','ARCHIVE','期中归档周次（建议第 9 周，需教务确认）',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(2,'archive.final.week','17','INT','ARCHIVE','期末归档周次（建议第 17 周，需教务确认）',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(3,'archive.window.days','7','INT','ARCHIVE','归档窗口开放天数',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(4,'archive.allow.admin.extend','true','BOOL','ARCHIVE','是否允许教务延长归档窗口',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(5,'notify.remind.interval.days','3','INT','NOTIFY','归档催办间隔天数',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(6,'notify.remind.max.times','3','INT','NOTIFY','归档最多催办次数',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(7,'coverage.soft.check.weeks','2','INT','COVERAGE','期内软提醒检查间隔周数',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(8,'coverage.soft.zero.weeks','4','INT','COVERAGE','连续零录入多少周触发软提醒',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(9,'questionnaire.flow.timeout.days','7','INT','QUESTIONNAIRE','问卷每个环节超时天数',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(10,'session.generate.weekday','1','INT','ATTENDANCE','课表默认上课星期（1=周一），批量生成 course_session 用',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46'),(11,'risk.dashboard.refresh.cron','0 30 2 * * ?','STRING','SYSTEM','风险状态批量刷新时间',1,NULL,'2026-10-17 21:09:46',NULL,'2026-10-17 21:09:46');
