  `item_code` varchar(30) NOT NULL DEFAULT 'OVERALL' COMMENT '评分项编码；整体级固定 OVERALL',
  `raw_delta` decimal(5,2) DEFAULT NULL COMMENT '未收缩的原始 Δ（班 vs 课程平均）',
