  `shrink_lambda` decimal(4,3) DEFAULT NULL COMMENT '收缩系数 λ = n/(n+k)，k 见 risk_engine_config',
  `sample_size` int NOT NULL DEFAULT '0' COMMENT '参与估计的样本量（学生数）',
  `std_dev` decimal(5,2) DEFAULT NULL COMMENT '样本标准差（异常检测用）',
  `fused` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否熔断：1停用该 Δ（|Δ| 超阈值，等教务复核）',
