  `review_by` bigint DEFAULT NULL COMMENT '复核人（教务ID）',
  `review_time` datetime DEFAULT NULL COMMENT '复核时间',
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE' COMMENT '状态：ACTIVE可用/INSUFFICIENT样本不足/FUSED已熔断/REVIEWED复核通过',
  `engine_version` varchar(20) DEFAULT NULL,
  `calc_time` datetime DEFAULT NULL COMMENT '估计时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_teacher_offering_item` (`teacher_id`,`offering_id`,`item_code`),
  KEY `idx_offering` (`offering_id`),
  KEY `idx_course_term` (`course_id`,`term_id`),
  KEY `idx_status` (`status`,`fused`)
) ENGINE=InnoDB AUTO_INCREMENT=6007 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='教师尺度Δ表（分项级，含收缩与熔断）';
